# AUTOGENERATED KERNEL (LLM)
# Source: LLM-generated candidate implementation
# Status: Experimental / uncurated
# Expectation: Correctness-first, performance not representative

import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_SIZE": bs},
        )
        for bs in [32, 64, 128, 256, 512, 1024, 2048, 4096]
    ],
    key=["n_elements"],
)
@triton.jit
def gelu_kernel(
    x_ptr,
    output_ptr,
    n_elements,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements

    x = tl.load(x_ptr + offsets, mask=mask)
    x = tl.load(x_ptr + offsets, mask=mask, other=0.0)
    out = 0.5 * x * (1.0 + tl.math.erf(x * 0.70710678118654752440))
    tl.store(output_ptr + offsets, out, mask=mask)


class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x_flat = x.view(-1)
        out_flat = torch.empty_like(x_flat)
        n_elements = x_flat.numel()
        grid = lambda META: (triton.cdiv(n_elements, META["BLOCK_SIZE"]),)
        gelu_kernel[grid](x_flat, out_flat, n_elements)
        return out_flat.view_as(x)
